WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_base_compare'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '基期比较', 'kp-xingce-data-base-compare', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基期比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "对多个逆向倒推的历史数据进行大小排序或最值选拔。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目给出今年各个主体的量和增长率，问：去年（基期）谁的量最大/最小？本质是比较多个分数的大小。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "每个选项背后都代表一个算式："}]}, {"type": "katexBlock", "attrs": {"content": "基期量 = \\frac{现期量}{1 + 增长率}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出所有待比选项的 现期量/(1+r)] --> B{是否存在明显的'大大'关系?}\nB -- 是(现期量极大且r极小) --> C[利用'大大则大'法则直接锁定最大项]\nB -- 否 --> D[剔除明显较小项, 留下神仙打架的两项]\nD --> E[使用化除为乘或差分法精算]\nE --> F[得出最终基期最大值]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年产值：甲为100亿(增5%)，乙为80亿(增15%)，丙为15亿(降2%)。求2022年产值最大的企业是谁？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：求基期量最大值，涉及三个分数比较。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第一轮排雷：丙的现期量(15)太小，无论分母是多少都不可能超过甲乙，直接淘汰丙。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第二轮比较：甲基期 = 100/1.05，乙基期 = 80/1.15。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "运用法则：甲的分子(100) > 乙的分子(80)，甲的分母(1.05) < 乙的分母(1.15)。分子大分母小，分数必然大！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：甲最大。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "傻傻算尽所有选项：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在四选一的基期比较题中，通常会有两个选项的现期量特别小，可以直接肉眼排除。真正需要你列式比较的往往只有两个选项。千万不要一开始就硬算四个基期量！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "多练“分子大分母小”的敏感度。只要能一眼看出“大大则大”的关系，就能省去90%的动笔时间。"}]}]}$$ AS jsonb), NULL, '基期比较的核心考点与实战推导。', category_node.id, CAST('["资料分析", "基期比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_base_compare", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
